from math import gcd

def count_colors(starts, ends):
    min_coloring = 2 ** (starts[0] - 1)
    for color in range(min_coloring, -1, -1):
        g = gcd(color, min_coloring-1)
        if any(color % (g + 1) == 0 for color in range(g, min_coloring, g + 1)):
            for skipped in range(g, min_coloring, g + 1):
                ends = [end for end in ends if end % skipped != 0]
                another = set()
                for a, b in combinations(ends, 2):
                    if (b - a) % gcd(a, b) == 0:
                        another.add(b - a)
                if another and not any(color % skipped == 0 for color in another):
                    continue
                colors = [1 / (i % g + 1) * (1 / gcd(g, i)) for i in range(g + 1, min_coloring + 1, g + 1)]
                if all(color * (1 - color / max(1, sum(colors)))**2 > 1 - 1e-9 for color in colors):
                    return int(color)
    return 1

def find_min_colors(intervals):
    min_colors = float('inf')
    for start, end in intervals:
        min_colors = min(min_colors, count_colors([start], [end]))
    for intervals, ends in zip(intervals, intervals):
        for end in ends:
            min_colors = min(min_colors, count_colors([start], [end]))
        ends = []
    return min_colors
