from collections import defaultdict

def construct_graph(edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
    return graph

def is_cactus(edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
    return cactus_test(graph)

def cactus_test(graph):
    nodes = set(graph.keys())

    def dfs(node, parent):
        for neighbor in graph[node]:
            if neighbor == parent:
                continue
            if neighbor in visited:
                return True
            if cactus_test(graph, neighbor):
                return True
        visited.add(node)
        return False

    visited = set()
    for node in nodes:
        if node not in visited:
            if dfs(node, None):
                return False
    return True

def count_degenerate_pairs(edges):
    graph = construct_graph(edges)
    count = 0
    for i in range(len(edges) - 1):
        for j in range(i + 1, len(edges)):
            new_graph = graph.copy()
            new_edges = edges[:i] + edges[j:i + 1] + edges[j + 1:]
            new_graph[(edges[i][0], edges[i][1])] = tuple(set(edges[j:j + 2]) - set([edges[i]]))
            new_graph[(edges[i][1], edges[i][0])] = tuple(set(edges[j:j + 2]) - set([edges[i]]))
            if not is_cactus(new_edges) or cactus_test(new_graph):
                count += 1
    return count

