from collections import defaultdict, deque
from typing import List

def find_shortest_path_grid(source, target):
    n = len(source)
    helper = defaultdict(list)

    for i in range(n):
        for j in range(i + 1, n):
            if source[i], source[j] in helper[source[j]]:
                helper[source[j]].remove(source[i])
            if source[j], source[i] not in helper[source[i]]:
                helper[source[i]].append(source[j])

    visited = [False for _ in range(len(source))]
    q = deque()
    t = 0

    q.append(source[t])
    visited[t] = True

    while len(q) > 0:
        u = q.popleft()
        for v in helper[u]:
            if not visited[v]:
                q.append(v)
                visited[v] = True

    return visited.index(target)-1

def main():
