    n = len(points)
    dp = [[float('inf')] * 2 for _ in range(n)]

    for i in range(n):
        for j in range(min(2, i + 2) - 1):
            d = (i // (j + 1)) * (points[i][0] - points[i - j - 1][0]) * 2
            if d + dp[i - j - 1][j] < dp[i][j]:
