from collections import defaultdict

def connected_components(edges):
    connected_components = 0
    roots = set()
    for edge in edges:
        u, v = edge
        if u not in roots and v not in roots:
            roots |= {u, v}
            connected_components += 1
    return len(roots)

def count_pairs(edges):
    m = len(edges)
    edges = sorted(edges, key=lambda x: x[1])
    max_val = 1
    roots = defaultdict(set)
    max_edges = defaultdict(int)
    for i, (u, v) in enumerate(edges):
        roots[u].add(i)
        roots[v].add(i)
        max_edges[u] = max(max_edges[u], i)
        max_edges[v] = max(max_edges[v], i)

    cycles = 0
    count = 0
    for u, edges in roots.items():
        if not edges:
            cycles += 1
        else:
            count += max_cycles(edges)

    for u, edges in roots.items():
        if u != 1:
            count += sum(edges) - max_val
            max_val *= 2

    return 2 * cycles * (cycles - 1) - count

def max_cycles(edges):
    cycles = 0
    max_edges = defaultdict(list)
    for i, e in enumerate(edges):
        c, n = divmod(max_edges[e], 2)
        if -c % 2 == -n % 2 and c > 0:
            max_edges[e].clear()
        else:
            while len(max_edges[e]) > c:
                e1, e2 = max_edges[e].pop(0)
                if len(max_edges[e]) == n:
                    max_edges[e1].append(e2)
                max_edges[e2].append(e1)
        if len(max_edges[e]) == max(0, 2 - n):
            cycles += 1
        max_edges[e].append(i)
        max_edges[e].sort()
    return cycles - max(0, 2 - cycles)

