import sys

class Uzhlyandia:
    def __init__(self, max_distance=10**8):
        self.max_distance = max_distance

    def manhattan_distance(self, point):
        x, y = point
        return abs(x) + abs(y)

    def find_lines(self, point):
        min_distance = sys.maxsize
        lines = []

        # Check vertical lines
        for dy in range(-self.max_distance, self.max_distance + 1):
            x = point[0] + dy
            dist = self.manhattan_distance((x, point[1]))
            if dist < min_distance:
                min_distance = dist
                lines = [dy]

        # Check horizontal lines
        for dx in range(-self.max_distance, self.max_distance + 1):
            y = point[1] + dx
            dist = self.manhattan_distance((point[0], y))
            if dist < min_distance:
                min_distance = dist
                lines = [dx]

        return lines


def main(max_distance):
    program_counter = 1

    while True:
        line = input().split()
        if line[0] == "0":
