            set_parents = set()
            for j in range(i + 1):
                for k in graph[j]:
                    set_parents.add(k)
            set_parents = set(map(lambda x: parents[x][k], graph) + parents[:i + 1])
            for k in graph:
                for j in k:
                    graph[j] = [c for c in graph[j] if c not in set_parents]
            node_temp = 0
            count = 0
            for i in range(M):
                if list(map(lambda x, y: x & y, graph[i], graph[powers])) != 1: count += 1
                if count == M - j - count: node_temp = i
            graph.pop(node_temp)
            M -= 1
            numEdges += 1
    answer = is_desert(graph, parents, numEdges)
    print(answer)
