    total_configs = 0
    for bitmask in range(1, (1 << k) + 1):
        config_sum = 0
        for j in range(k):
            if bitmask & (1 << j):
                config_sum += a[j]
        if config_sum % (k - 1) == 0:
            if bitmask == (1 << k) - 1:
                total_configs += 1
            else:
                total_configs += mod_exponentiation(-1, (k - 1) * (k + 1) // 2, MOD)
