from collections import defaultdict, deque

def dijkstra(roads, n):
    time = [float('inf') for _ in range(n)]
    time[0] = 0
    q = deque([0])

    while q:
        wp = q.popleft()
        for to in roads[wp]:
            if time[wp] == time[to]:
                break
            if time[wp] + 1 < time[to]:
                time[to] = time[wp] + 1
                q.append(to)

    return time

def solve(n, roads, q):
    time = dijkstra(roads, n)
    for n, m in q:
        if time[n] > time[m]:
            print('INF')
        else:
            print(time[n] - 1)

