def lnds(sequence):
    """
    Length of Longest Non-Decreasing Subsequence
    """
    stack = []
    for num in sequence:
        if not stack or stack[-1] < num:
            stack.append(num)
        else:
            stack[stack.index(min(stack)):] = num
    return len(stack)

