from math import comb, factorial

def lnds(arr, mod=998244353):
    n = len(arr)
    dp = [[0] * n for _ in range(n)]
    for length in range(1, n + 1):
        for i in range(n + 1 - length):
            j = i + length - 1
            for k in range(i, j + 1):
                if not arr[k] <= arr[i]:
                    break
                if k == i:
                    dp[i][j] = ((dp[i][j - 1] + 1) * comb(j - i, k - i) % mod) * k
                elif k == j:
                    dp[i][j] = ((dp[i + 1][j - 1] + 1) * comb(i - j, k - j) % mod) * k
                else:
                    dp[i][j] = (dp[i][i-1] + 1 + mod - dp[i + 1][j - 1] - 1) * k % mod - dp[i + 1][k - 1] * 2 % mod
    return dp[0][-1]

