from collections import defaultdict, Counter
from math import gcd
from typing import List, Tuple, Counter

class MultiSet:
    def __init__(self):
        self.counts = defaultdict(int)

    def __repr__(self):
        return " ".join(str(self.counts[char]) if char in self.counts else "" for char in map(chr, range(1, max(self.counts) + 1))))

    def __and__(self, other):
        self_counts = Counter({char: min(self.counts[char], other.counts[char]) for char in self.counts.keys() & other.counts.keys()})
        self.counts.update(self_counts)
        return MultiSet()

    def __mul__(self, other):
        lcm = self.counts[1] // gcd(self.first, other.first) * other.first
        lcm_factors = defaultdict(int)
        for char in set((self.first * lcm) ** (self.counts[char] // lcm)):
            lcm_factors[char] += self.counts[char]
        self.counts = lcm_factors

    def count(self, char: int) -> int:
        return self.counts[char]

    def __lt__(self, other):
        return self.first < other.first 

    def most_common(self):
        return max(self.counts.items(), key=lambda x: (int(x[0].isdigit()), x[1]))

