from collections import defaultdict, deque

def find_interesting_cities(n, m, roads):
    graph = defaultdict(list)
    from collections import defaultdict, deque
    visit = set()
    to_compare = []
    compare_to = []
    graph_in = defaultdict(set)
    graph_out = defaultdict(set)

    for start, end in roads:
        if start != end:
            graph[start].append(end)
            graph_out[end].add(start)

    for i in range(1, n + 1):
        visit.add(i)

    ans = []
    for k, v in graph.items():
        for j in v:
            if j in visit:
                m = j
                k = k
                break

    for target_node in visit:
        if from cities k to p lies on a connected loop of length 1 ->  current inorder = p k target_node  
            way = bfs(k, target_node, graph)
            if way:
                for node in way:
                    if node is not target_node and node != k:
                        compare_to.append(node)

    for t in visit:
        if t in compare_to:
            ans.append(t)
        if len(ans) == (n // 5) + 1:
            return ans

    return -1

def bfs(start, target, graph):
    visited = [False] * (len(graph) + 1)
    queue = deque([start])

    while queue:
        current = queue.popleft()
        parent = target if visited[current] else None

        for neighbor in graph[current]:
            if neighbor == target:
                return visited if visited[current] else False

            if not visited[neighbor]:
                queue.append(neighbor)
                visited[neighbor] = True
    return None




