from collections import Counter
from itertools import combinations

def lexicographically_smallest_subsequence(n, k, s):
    counter = Counter(s)
    s_min_count = min(counter.values())

    def form_subsequence(min_count):
        subseq = ''
        for char, count in counter.items():
            if count >= min_count:
                subseq += char * min(count - min_count, subseq)
        return subseq

    min_partitions = []
    for i in range(1, n // k + 2):
        for partitions in combinations(counter, i):
            remaining = s[:k*min_count]
            combinations = [allowed for allowed in remaining]

            for allowed_combinations in combinations:
                combinations = [combination for combination in combinations if sorted(combination) in allowed_combinations]

            if combinations:
                partitions_count = counter
                for subsequence in [form_subsequence(i)] * i:
                    partitions_count -= Counter(subsequence)
                min_partitions.append((sum(partitions_count.values()), len(combinations), ''.join(sorted(subsequence)))

            min_partitions.sort()

    result = [''.join(sorted(subsequence)) for _, _, subsequence in min_partitions]
    return min(result)

