import sys

def count_critical_edges():
    n, m = map(int, input().split())
    edges = [[int(x) - 1 for x in input().split()] for _ in range(m)]

    if m == 1 and edges[0][0] == edges[0][1]:
        return 0

    connected_components = []

    for i in range(m):
        u, v = edges[i]

        connected_components.append([])
        for j in range(m):
            if (edges[j][0] == u or edges[j][0] == v) or (edges[j][1] == u or edges[j][1] == v):
                if [edges[j][0], edges[j][1]] not in connected_components[-1]:
                    connected_components[-1].append([edges[j][0], edges[j][1]])
        connected_components[-1].remove([u, v])

    for comp in connected_components:
        cc_m = len(comp)
        edges_in_cactus = 0

        for i in range(cc_m):
            for j in range(i + 1, cc_m):
                u, v = comp[i], comp[j]
                for k in range(m):
                    if k < i and k > j:
                        if tuple(sorted([] + edges[k])) in comp:
                            edges_in_cactus += 1
                            break

        for i in range(cc_m):
            for j in range(i + 1, cc_m):
                u, v = comp[i], comp[j]
                for k in range(m):
                    if k < i and k > j:
                        for a, b in edges[k]:
                            if u == a and v == b:
                                edges_in_cactus += 2

    return 2 * edges_in_cactus

